IDS = ["YM-069","YM-070","YY-006","YY-010","YY-011","YY-012","YY-013","YY-014","YY-015","YY-016","YY-017","YY-018","YY-019","YY-020","YY-021","YY-022","YY-023","YY-024","YY2-001","YY2-002"]
def main():
    assert len(DATA) == 20, len(DATA)
    assert [d["case_id"] for d in DATA] == IDS
    os.makedirs(OUT, exist_ok=True)
    cm = ru = di = 0
    for d in DATA:
        assert set(d.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, d["case_id"]
        assert set(d["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
        assert 0.0 <= d["confidence"] <= 1.0
        p = os.path.join(OUT, d["case_id"] + ".json")
        assert not os.path.exists(p), "refuse overwrite: " + p
        with open(p, "x", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        cm += bool(d["trigger"]["changed_main"]); ru += bool(d["trigger"]["reserve_used"]); di += bool(d["trigger"]["disputed"])
    # per-file self-verify: reopen each exactly by id
    for cid in IDS:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            r = json.load(f)
        assert r["case_id"] == cid and r["prediction_text"] and r["basis"]
    print(f"written=20 changed_main={cm} reserve_used={ru} disputed={di}")
if __name__ == "__main__":
    main()
